package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaUzDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Mening amallarim yomonligidan panoh", "Allohim, qilgan ishimning yomonligidan va qilmagan ishimning yomonligidan Sendan panoh tilayman.", "Payg'ambarning duosi ﷺ, Oisha (RA).", "Amalga oshirilgan va bajarilmagan narsalarning oqibatlaridan himoya qilish."),
        "dua_jahdil_bala" to DuaText("Og'ir sinovlardan boshpana", "Allohim, qattiq fitnadan, musibat yetib qolishidan, yomon hukmdan va dushmanlarning maqtovidan panoh tilayman.", "Og'ir sinovlardan va dushmanlarning g'azabidan boshpana.", "Payg'ambar ﷺ bu to'rt narsadan panoh so'radi."),
        "dua_fitnat_ghina_faqr" to DuaText("Boylik va qashshoqlik sinovlaridan panoh", "Allohim, dangasalik va qarilikdan, gunoh va qarzdan, qabr fitnasi va azobidan, do'zax fitna va azobidan, boylik fitnasining yomonligidan va faqirlik fitnasidan Sendan panoh so'rayman.", "Qabr, jahannam, boylik va faqirlik sinovlaridan panoh (duoning bir qismi).", "Payg'ambardan keng qamrovli panoh duosi ﷺ."),
        "dua_kufr_faqr" to DuaText("Kufr va faqirlikdan panoh", "Allohim, sendan kufr va faqirlikdan panoh tilayman va qabr azobidan panoh tilayman. Sendan boshqa iloh yo'q.", "Ertalab va kechqurun uch marta.", "Abu Bakra (RA) Rasulullohning ﷺ bu gaplarini eshitdilar."),
        "dua_sharri_sami" to DuaText("Mening hislarim yomonligidan panoh", "Allohim, qulog‘imning yomonligidan, ko‘zimning yomonligidan, tilimning yomonligidan, qalbimning yomonligidan va nafsim yomonligidan Sendan panoh so‘rayman.", "Shakal ibn Humaydga oʻrgatgan (RA).", "A'zolarni va nafsni gunohdan saqlash uchun duo."),
        "dua_hadm_gharaq" to DuaText("To'satdan o'lim va baxtsiz hodisalardan panoh", "Allohim, (bino tomonidan ezilib qolishdan), balandlikdan qulashdan, cho'kishdan, kuyishdan va qarilikdan panoh tilayman; O'lim paytimda shaytondan adashtirishdan, Sening yo'lingdan qochib o'lishdan va (zaharli) chaqishdan o'lishdan.", "Baxtsiz hodisalar va yomon o'limdan boshpana.", "Payg'ambardan panoh duosi ﷺ."),
        "dua_ju_khiyanah" to DuaText("Ochlik va xiyonatdan boshpana", "Allohim, ochlikdan panoh tilayman, chunki u yomon hamrohdir va xiyonatdan panoh tilayman, chunki u yomon sirdoshdir.", "Ochlik va xiyonatdan panoh.", "Payg'ambardan panoh duosi ﷺ."),
        "dua_huda_tuqa" to DuaText("Hidoyat, taqvo, iffat va yetarlilik", "Allohim, sendan hidoyat, taqvo, iffat va nafsni so'rayman.", "Payg'ambarning qisqa, keng qamrovli duolari ﷺ.", "Din va dunyoning to'rt ne'mati."),
        "dua_aslih_li_dini" to DuaText("Dinimni, dunyo va oxiratimni isloh qil", "Allohim, barcha ishlarimni himoya qiluvchi dinimni isloh qil. Mening rizqim bo'lgan dunyo hayotimni isloh qil. Va oxiratimni to'g'rilab qo'ying, men unga qaytaman. Menga hayotni har bir yaxshilikda ziyoda qilgin va o‘limni har bir yomonlikdan xalos qilgin.", "Dinni isloh qilish, dunyo va oxirat — uchalasi ham.", "Payg'ambarning to'liq duosi ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Qalblarimizni O'zingga itoat et", "Ey qalblarni o'giruvchi Allohim, qalblarimizni O'zingga itoat et.", "Qalbni itoatda mustahkam tutish uchun duo.", "Barcha insonlarning qalblari Rahmonning ikki barmog'i orasidadir."),
        "dua_jannah_nar" to DuaText("Jannat so'rash, Do'zaxdan panoh", "Allohim, sendan jannatni so'rayman va sendan do'zaxdan panoh tilayman.", "Tashahhuddan keyin yoki istalgan vaqtda.", "Payg'ambar ﷺ aytdilar: \"Bizning duolarimiz ham shu narsa atrofidadir\"."),
        "dua_khayri_kullih" to DuaText("Hammasi yaxshi, hozir va keyin", "Allohim, men Sendan barcha yaxshiliklarni - yaqin va kechikkan, bilgan va bilmagan narsalarni - so'rayman va barcha yomonliklardan - yaqin va kechiktirilgan, bilgan va bilmagan narsalarimdan panoh so'rayman. Allohim, men sendan jannatni va meni unga yaqinlashtiradigan har qanday so'z va amalni so'rayman va do'zaxdan va meni unga yaqinlashtiradigan har qanday so'z va amaldan Sendan panoh tilayman.", "Payg'ambar ﷺ bu keng qamrovli duoni Oishaga (RA) (duoning bir qismi) o'rgatgan.", "Har bir yaxshilikni to'playdigan duo."),
        "dua_ihdini_saddidni" to DuaText("Menga yo'l ko'rsating va meni to'g'ri tuting", "Allohim, meni hidoyat qil va to'g'ri yo'lda tutgin.", "Payg'ambar ﷺ buni Aliga o'rgatgan (RA).", "Hidoyatni yo'l bo'ylab, sadadni esa o'qning to'g'riligidek tasavvur qiling."),
        "dua_hubbaka" to DuaText("Allohning sevgisini so'rash", "Allohim, sendan sevgingni, seni sevganlarning sevgisini va meni sevgingga yetkazuvchi amallarni so'rayman. Allohim, sevgingni menga o'zimdan, oilamdan va sovuq suvdan sevimliroq qil.", "Dovudning duosi (AS) Payg'ambar ﷺ.", "Allohga muhabbat eng katta boylikdir."),
        "dua_filal_khayrat" to DuaText("Yaxshilik qilish va yomonlikni tark etish", "Allohim, sendan yaxshi amallar qilishimga, yomonliklarni tark etishimga va miskinlarni yaxshi ko‘rishga, meni mag‘firat qilishingni va rahm qilishingni so‘rayman. Qachonki bir qavmga imtihon qilishni xohlasang, meni imtihon qilinmay ol. Men Sendan sevgingni, Seni sevganlarning sevgisini va meni sevgingga yaqinlashtiruvchi amallar sevgisini so'rayman.", "Alloh bu duoni Payg'ambarga ﷺ tushida o'rgatgan.", "Payg'ambarimiz ﷺ dedilar: \"To'g'ri, uni o'rganing va o'rgating\"."),
        "dua_bi_ilmikal_ghayb" to DuaText("Hayot yaxshi bo'lsada yashashga ruxsat bering", "Allohim, g‘ayb ilmi va maxluqot ustidan qudrating ila, toki hayot men uchun yaxshiroq ekanini bilguningcha meni tirik tutgin va o‘lim men uchun afzalroq ekanini bilganingda meni o‘zingga olgin. Allohim, sendan maxfiy va oshkora qo'rquvni, qanoat va g'azabda haq so'zni, faqirlikda va boylikda o'rtacha bo'lishni so'rayman.", "Ammor ibn Yosirning duosi (RA) (ochilish qismi).", "Payg'ambar ﷺ bu duoni namozda qilgan."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Allohim, sendan so'rayman, chunki senga hamdlar bor. Sendan o'zga iloh yo'q, ne'matlar ato etuvchi, osmonlaru erni yaratuvchi. Ey azizlik va izzat sohibi, ey barhayot, ey Parvardigor!", "Rasululloh sollallohu alayhi vasallam ﷺ dedilarki, bu odam Allohning buyuk ismi bilan duo qildi.", "Bu ism bilan qilingan duo ijobat bo'ladi."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad as-Samad", "Allohim, Sendan so'rayman, guvohlik beramanki, Sen Allohsan. Sendan o'zga iloh yo'q. Yagona, o'ziga etarlidir. U tug'maydigan va tug'ilmagan va Unga teng keladigani yo'q.", "Rasululloh sollallohu alayhi vasallam ﷺ dedilar.", "U bilan so'ralsa, beradi; u tomonidan chaqirilganda, U javob beradi."),
        "dua_thabbitni_hadiyan" to DuaText("Meni qat'iy, yo'naltiruvchi va yo'lboshchi qil", "Allohim, meni mustahkam qilgin va meni hidoyat qiluvchi va hidoyat qilguvchi qilgin.", "Payg'ambarimiz ﷺ Jarir (RA) uchun bu duoni o'qidilar (o'zingiz uchun \"sabbitni\" deb ayting).", "Jarir (RA) uchun asl duoda \"sabbit-hu\" so'zlari ishlatilgan."),
        "dua_rabbighfir_tub_alayya" to DuaText("Meni kechir va tavbalarimni qabul qil", "Parvardigorim, meni kechir va tavbalarimni qabul qil. Albatta, Sen tavbalarni qabul qiluvchi va rahmlisan.", "Bir o'tirishda yuz marta - Payg'ambarning amaliyoti ﷺ.", "Sahobalar Payg‘ambar alayhissalomni bir o‘tirishda yuz marta aytganlarini ﷺ ta sanashgan."),
        "dua_rafiq_ala" to DuaText("O'layotgan odamning duosi", "Allohim, meni kechir, menga rahm qil va meni eng oliy sahobaga qo‘sh.", "Payg'ambar sollallohu alayhi vasallamning oxirgi duolari ﷺ - kasal odam o'zi uchun aytadi.", "Payg'ambarimiz ﷺ bu duoni vafot etganlarida qilganlar."),
        "dua_la_bas_tahur" to DuaText("Bemorlarga tasalli berish: poklanish", "Zarar yo'q; Agar Alloh xohlasa, bu (gunohlardan) poklanishdir.", "Kasallarni ziyorat qilganda taskin berish uchun.", "Payg'ambarimiz ﷺ kasallarni ziyorat qilganlarida shunday deganlar."),
        "dua_talqeen" to DuaText("O'lganlar uchun Talqeen", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas.", "O'layotgan odamning yonida kalima o'qing (ularni aytishga majburlamang).", "Kimning oxirgi so'zi \"La ilaha illalloh\" bo'lsa, jannatga kiradi (Abu Dovud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("O'limni orzu qilish o'rniga", "Allohim, toki hayot men uchun yaxshiroq bo'lsa, meni omon qil, o'lim yaxshi bo'lsa, meni ol.", "Qiyinchilikda o'limni tilash o'rniga.", "Payg'ambar ﷺ o'limni orzu qilishni man qilgan va o'rniga buni o'rgatgan."),
        "dua_for_one_i_cursed" to DuaText("So'zlar bilan xafa qilgan inson uchun", "Allohim, men kimni haqorat qilgan boʻlsam, uni qiyomat kunida oʻzingga yaqinlashtiruvchi vasila qilgin.", "Siz jahl bilan yomon gapirgan kishi uchun.", "Payg'ambarning duosi ﷺ."),
        "dua_praising_someone" to DuaText("Birovni maqtashda", "Men falonchini mana shunday deb bilaman va Alloh uning hisobchisidir va men Alloh huzurida hech kimning pokligiga kafolat bermayman.", "Birovni maqtaganda, bo'rttirib yuborish o'rniga.", "Payg'ambar ﷺ maqtovning bu odobini o'rgatgan."),
        "dua_being_praised" to DuaText("Sizni maqtashganda", "Allohim, ular aytgan gaplari uchun mendan hisob-kitob qilmagin va bilmaganlarini kechirgin.", "O'z-o'zini maqtashni eshitib - sahobaning amaliyoti (RA).", "Maqtov paytida takabburlikdan qochishning bir usuli."),
        "dua_non_muslim_sneezes" to DuaText("Musulmon bo'lmagan odam aksirganda", "Alloh sizni hidoyat qilsin va ishlaringizni isloh qilsin.", "Musulmon bo'lmagan kishi aksirib \"Alhamdulillah\" desa.", "Yahudiylar Rasululloh ﷺ «Yarhamukalloh» deyishlarini umid qilib, huzurlarida aksirishardi va u buni aytadi."),
        "dua_reply_ahl_kitab_salam" to DuaText("Ahli kitoblar salomiga javob", "Va sizga.", "Ahli kitoblar salom bersalar.", "Payg'ambarning ko'rsatmasi ﷺ."),
        "dua_fasting_invited" to DuaText("Ro'za tutayotganda taklif qilinganda", "Men ro'za tutyapman.", "Ro'za vaqtida taklif qilinganda yoki kimdir siz bilan janjallashganda.", "Ro‘zador taklifni qabul qilsa, uy egasi uchun duo qilishi kerak."),
        "dua_for_who_gave_drink" to DuaText("Meni ovqatlantirgan kishi uchun", "Allohim, meni to'ydirganni ovqatlantirgin va menga ichtirganni ichirgin.", "Kim sizga ovqat yoki ichimlik bersa.", "Rasululloh ﷺ bu duoni al-Miqdod (RA) uchun qilganlar."),
        "dua_eid_greeting" to DuaText("Hayit tabriklari", "Alloh bizdan va sizdan (yaxshi amallarni) qabul qilsin.", "Hayit kuni bir-birlariga — sahobai sahobalarning amali (RA).", "Buni sahobalar hayitda uchrashganlarida aytishgan."),
        "dua_wedding_night" to DuaText("Nikohdan keyin kelin uchun", "Allohim, men Sendan uning yaxshiligini va uni yaratgan tabiatingning yaxshiligini so'rayman va uning yomonligidan va uni yaratgan tabiatingning yomonligidan Sendan panoh tilayman.", "Nikohdan keyin qo'lni xotinning peshonasiga qo'yish.", "Payg'ambarning ﷺ ta'limoti - nikohda baraka."),
        "dua_istisqa_ibadak" to DuaText("Xizmatkorlaringizni va hayvonlaringizni sug'oring", "Allohim, bandalaring va hayvonlaringga suv ber, rahmatingni yoygin va o'lik yurtingni tiriltirgin.", "Yomg'ir so'rash (istisqa).", "Payg'ambar ﷺ bu duoni yomg'ir uchun qilgan."),
        "dua_seeing_clouds" to DuaText("Qora bulutlarni ko'rish", "Allohim, uning yomonligidan Sendan panoh tilayman.", "Osmonda qora bulutlarni ko'rishda; yomg'ir yog'sa, \"Allohumma sayyiban nafi'a\" deb ayt.", "Rasululloh ﷺ bulutlarni ko'rganlarida qilgan ishlarini tashlab, shu duoni qilardilar."),
        "dua_jamarat" to DuaText("Jamaratni toshbo'ron qilish", "Alloh eng buyukdir.", "Otilgan har bir tosh bilan.", "Rasululloh sollallohu alayhi vasallam ﷺ har bir tosh bilan takbir aytdilar, so'ngra birinchi va ikkinchi jamradan keyin qiblaga qarab uzoq duo qildilar."),
        "dua_rabbi_ainni" to DuaText("Robbim, menga yordam ber, menga qarshi emas", "Parvardigorim, menga yordam ber va menga qarshi boshqalarga yordam berma, menga g‘alaba ber va boshqalarni ham menga g‘alaba berma, men uchun reja tuz va menga qarshi reja tuzma, meni hidoyat qil va hidoyatimni oson qil va kim menga zulm qilsa, menga yordam ber.", "Payg'ambarning keng qamrovli duosi ﷺ (ochilish qismi).", "Dinda va dunyoda har qanday yordamni to'playdigan duo."),
        "dua_ati_nafsi_taqwaha" to DuaText("Ruhimga taqvoni ato et", "O Allah, grant my soul its piety and purify it, for You are the best to purify it. Sen uning qo'riqchisi va xo'jayinisan.", "Nafsni isloh qilish va poklash uchun.", "Rasululloh ﷺ bu duoni qilardilar."),
        "dua_iqsim_lana_khashyatik" to DuaText("Bizga o'zingdan shunday qo'rquvni nasib et", "Allohim, oramizga kirib qolishimizdan va O'zingga osiy bo'lishingdan qo'rqishimizni, jannatingga olib kirishimiz uchun yetarlicha itoatni va dunyo balolarini biz uchun oson qilish uchun yetarlicha ishonchni ato et. Eshitishimiz, ko'rishimiz va kuchimizdan bahramand bo'laylik, modomiki bizni tirik saqlasang va ularni bizdan uzoqroq qil. Bizga zulm qilganlardan qasos ol, dushmanlarimizdan bizga yordam ber, musibatimizni dinimizda bo‘lmasin, bu dunyoni bizning eng katta tashvishimiz yoki ilmimizning chegarasi qilmagin va bizga rahm qilmaydiganlarni qo‘ymagin.", "Yig'ilishdan turganda - Payg'ambar ﷺ bu duoni o'qimasdan kamdan-kam turdilar.", "Din, dunyo va oxirat yaxshiligi uchun keng qamrovli duo."),
        "dua_infani_bima_allamtani" to DuaText("Menga o'rgatgan narsang bilan menga foyda ber", "Allohim, menga o'rgatgan narsang bilan menga foyda ber, menga foyda keltiradigan narsani o'rgat va ilmimni ziyoda qil.", "Bilim izlayotganda yoki o'qishdan oldin.", "Foydali ilm va unga amal qilish uchun duo."),
    )
}
